101	    @Test
102	    void cancelReleasesSlotsAndKeepsHistory() throws Exception {
103	        String section = key("SEC");
104	        String released = key("SCH");
105	        createPlan(released, occ("G1", section, iso(8), iso(9)));
106	        publishPlan(released, key("REQ"));
107	
108	        mvc.perform(post("/api/v1/plans/{key}/cancel", released)
109	                        .contentType(MediaType.APPLICATION_JSON)
110	                        .content(actionBody(key("REQ"))))
111	                .andExpect(status().isOk());
112	
113	        // 历史计划与原始占用保留
114	        MvcResult detail = mvc.perform(get("/api/v1/plans/{key}", released))
115	                .andExpect(status().isOk()).andReturn();
