3	import static org.assertj.core.api.Assertions.assertThat;
4	
5	import com.example.starter.plan.service.PlanService;
6	import com.example.starter.plan.web.ApiException;
7	import com.example.starter.plan.web.dto.CreatePlanRequest;
8	import com.example.starter.plan.web.dto.OccupancyRequest;
9	import com.example.starter.plan.web.dto.PlanResponse;
10	import com.example.starter.plan.web.dto.PublishedSlotView;
11	import com.example.starter.plan.web.dto.UpdateOccupanciesRequest;
12	import java.time.Instant;
13	import java.time.LocalDate;
14	import java.time.ZoneId;
15	import java.util.ArrayList;
16	import java.util.List;
17	import java.util.UUID;
18	import java.util.concurrent.Callable;
19	import java.util.concurrent.CountDownLatch;
20	import java.util.concurrent.ExecutorService;
21	import java.util.concurrent.Executors;
22	import java.util.concurrent.Future;
23	import java.util.concurrent.TimeUnit;
24	import org.junit.jupiter.api.Test;
25	import org.springframework.beans.factory.annotation.Autowired;
26	import org.springframework.boot.test.context.SpringBootTest;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.jdbc.core.JdbcTemplate;
29	
30	/**
31	 * 并发与幂等竞态测试：并发发布互斥、同键并发创建、更新与发布按提交顺序生效、
32	 * 取消不误释放其他计划时隙。
33	 */
34	@SpringBootTest
35	class PlanConcurrencyTest {
36	
37	    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
38	    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);
39	
40	    @Autowired
41	    private PlanService service;
42	
43	    @Autowired
44	    private JdbcTemplate jdbc;
45	
46	    @Test
47	    void concurrentPublishSameSectionOnlyOneSucceeds() throws Exception {
48	        String section = key("SEC");
49	        int contenders = 4;
50	        List<String> scheduleKeys = new ArrayList<>();
51	        for (int i = 0; i < contenders; i++) {
52	            String scheduleKey = key("SCH");
53	            createDraft(scheduleKey, section, 8, 9);
54	            scheduleKeys.add(scheduleKey);
55	        }
56	
57	        List<Outcome> outcomes = runConcurrently(scheduleKeys.stream()
58	                .<Callable<Outcome>>map(sk -> () -> {
59	                    try {
60	                        service.publish(sk, key("REQ"));
61	                        return Outcome.OK;
62	                    } catch (ApiException e) {
63	                        assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
64	                        return Outcome.CONFLICT;
65	                    }
66	                }).toList());
67	
68	        assertThat(outcomes.stream().filter(o -> o == Outcome.OK).count()).isEqualTo(1);
69	        assertThat(outcomes.stream().filter(o -> o == Outcome.CONFLICT).count())
70	                .isEqualTo(contenders - 1);
71	
72	        // 最终该区段只有一张计划的时隙生效
73	        List<PublishedSlotView> slots = service.getPublishedSlots(DAY, section);
74	        assertThat(slots).hasSize(1);
75	    }
76	
77	    @Test
78	    void concurrentCreateSameKeyReturnsFirstResult() throws Exception {
79	        String scheduleKey = key("SCH");
80	        String requestKey = key("REQ");
81	        String section = key("SEC");
82	        int threads = 4;
83	
84	        List<OccupancyRequest> occupancies = List.of(occ(section, 8, 9));
85	        List<Callable<PlanResponse>> tasks = new ArrayList<>();
86	        for (int i = 0; i < threads; i++) {
87	            tasks.add(() -> service.createDraft(new CreatePlanRequest(
88	                    requestKey, scheduleKey, DAY, occupancies)));
89	        }
90	        ExecutorService pool = Executors.newFixedThreadPool(threads);
91	        CountDownLatch ready = new CountDownLatch(threads);
92	        CountDownLatch go = new CountDownLatch(1);
93	        List<Future<PlanResponse>> futures = tasks.stream()
94	                .map(t -> pool.submit(() -> {
95	                    ready.countDown();
96	                    go.await();
97	                    return t.call();
98	                })).toList();
99	        ready.await();
100	        go.countDown();
101	        List<PlanResponse> responses = new ArrayList<>();
102	        for (Future<PlanResponse> f : futures) {
103	            responses.add(f.get(30, TimeUnit.SECONDS));
104	        }
105	        pool.shutdown();
106	
107	        // 全部返回首次结果，且库里只有一张计划
108	        assertThat(responses).allMatch(r -> r.equals(responses.get(0)));
109	        Integer count = jdbc.queryForObject(
110	                "SELECT COUNT(*) FROM rail_day_plan WHERE schedule_key = ?",
111	                Integer.class, scheduleKey);
112	        assertThat(count).isEqualTo(1);
113	    }
114	
115	    @Test
116	    void concurrentUpdateAndPublishApplyInCommitOrder() throws Exception {
117	        String section = key("SEC");
118	        String scheduleKey = key("SCH");
119	        createDraft(scheduleKey, section, 8, 9);
120	
121	        List<Outcome> outcomes = runConcurrently(List.of(
122	                () -> {
123	                    try {
